            if len({grid[r][c] for r in range(h)}) == 1:
                divider = ("col", c)
                break

    axis, k = divider
    if axis == "row":
        first = grid[:k]
        second = grid[k + 1:]
    else:
        first = [row[:k] for row in grid]
        second = [row[k + 1:] for row in grid]

    colors1 = {v for row in first for v in row}
    colors2 = {v for row in second for v in row}
    shared = colors1 & colors2
    background = next(iter(shared)) if shared else first[0][0]

    return [
